CREATE TABLE IF NOT EXISTS client_contracts (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,contract_code VARCHAR(30) NOT NULL,contract_number VARCHAR(100) NULL,project_id BIGINT UNSIGNED NOT NULL,client_id BIGINT UNSIGNED NOT NULL,client_contact_id BIGINT UNSIGNED NULL,pricing_method VARCHAR(20) NOT NULL,contract_date DATE NOT NULL,start_date DATE NULL,expected_end_date DATE NULL,contract_value DECIMAL(18,2) NULL,markup_percentage DECIMAL(7,4) NULL,title VARCHAR(190) NOT NULL,description TEXT NULL,terms TEXT NULL,notes TEXT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_client_contracts_code(contract_code),UNIQUE KEY uq_client_contracts_number(contract_number),UNIQUE KEY uq_client_contracts_project(project_id),KEY idx_client_contracts_client(client_id),KEY idx_client_contracts_contact(client_contact_id),KEY idx_client_contracts_filters(pricing_method,status,contract_date),CONSTRAINT fk_client_contracts_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE RESTRICT,CONSTRAINT fk_client_contracts_client FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE RESTRICT,CONSTRAINT fk_client_contracts_contact FOREIGN KEY(client_contact_id) REFERENCES client_contacts(id) ON DELETE SET NULL,CONSTRAINT chk_client_contracts_pricing CHECK(pricing_method IN('cost_plus','boq','lump_sum')),CONSTRAINT chk_client_contracts_status CHECK(status IN('draft','active','suspended','completed','cancelled')),CONSTRAINT chk_client_contracts_dates CHECK(start_date IS NULL OR expected_end_date IS NULL OR expected_end_date>=start_date),CONSTRAINT chk_client_contracts_value CHECK(contract_value IS NULL OR contract_value>=0),CONSTRAINT chk_client_contracts_markup CHECK(markup_percentage IS NULL OR markup_percentage>0),CONSTRAINT chk_client_contracts_method_values CHECK((pricing_method='cost_plus' AND markup_percentage IS NOT NULL) OR (pricing_method='boq' AND markup_percentage IS NULL) OR (pricing_method='lump_sum' AND contract_value IS NOT NULL AND markup_percentage IS NULL)),CONSTRAINT chk_client_contracts_active_number CHECK(status<>'active' OR contract_number IS NOT NULL)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
